add_action( 'woocommerce_checkout_create_order', 'perfectpixel_save_terms_acceptance', 10, 2 );
add_action( 'woocommerce_admin_order_data_after_billing_address', 'perfectpixel_show_terms_acceptance' );

function perfectpixel_save_terms_acceptance( $order, $data ) {
	if ( empty( $_POST['terms'] ) || ! wc_terms_and_conditions_checkbox_enabled() ) { // phpcs:ignore WordPress.Security.NonceVerification
		return;
	}
	$order->update_meta_data( '_perfectpixel_terms_accepted', current_time( 'mysql' ) );
	$order->update_meta_data( '_perfectpixel_terms_page_id', wc_terms_and_conditions_page_id() );
}

function perfectpixel_show_terms_acceptance( $order ) {
	$accepted = $order->get_meta( '_perfectpixel_terms_accepted' );
	if ( ! $accepted ) {
		return;
	}
	$page_id = (int) $order->get_meta( '_perfectpixel_terms_page_id' );
	printf(
		'<p><strong>%1$s</strong> %2$s%3$s</p>',
		esc_html( '{{terms_admin_label}}' ),
		esc_html( mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $accepted ) ),
		$page_id ? ' — <a href="' . esc_url( get_permalink( $page_id ) ) . '" target="_blank">' . esc_html( get_the_title( $page_id ) ) . '</a>' : ''
	);
}
